  top: 0;
  z-index: 40;
  background: rgba(13, 17, 23, 0.88);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}

.topbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.9rem 0;
}

.brand { font-weight: 700; letter-spacing: 0.3px; color: #fff; }
.brand span { color: var(--accent); }

.nav-links {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.nav-links a {
  color: var(--muted);
  padding: 0.35rem 0.55rem;
  border-radius: 8px;
}

.nav-links a.active,
.nav-links a:hover {
  color: var(--text);
  background: var(--bg-soft);
  text-decoration: none;
}

.hero {
  padding: 4.2rem 0 2.2rem;
}

.hero h1 {
  margin: 0 0 0.8rem;
  font-size: clamp(1.9rem, 4vw, 3rem);
  line-height: 1.1;
}

.hero p {
  margin: 0;
  max-width: 740px;
  color: var(--muted);
  font-size: 1.05rem;
}

.section { padding: 2rem 0; }
.section h2 { margin: 0 0 0.75rem; font-size: 1.6rem; }
.section p.lead { margin: 0 0 1.25rem; color: var(--muted); }

.grid {
  display: grid;
  gap: 1rem;
}
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }

.card {
  background: linear-gradient(165deg, rgba(18, 26, 36, 0.95), rgba(15, 22, 32, 0.95));
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1rem;
  box-shadow: 0 8px 24px var(--card-glow);
}

.card h3 { margin: 0 0 0.45rem; font-size: 1.08rem; }
.card p { margin: 0 0 0.8rem; color: var(--muted); }
.card .tag {
  display: inline-block;
  margin-bottom: 0.55rem;
  font-size: 0.77rem;
  color: #a7f3d0;
  background: rgba(34, 197, 94, 0.1);
  border: 1px solid rgba(34, 197, 94, 0.35);
  padding: 0.2rem 0.46rem;
  border-radius: 999px;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--accent);
  color: #021318;
  background: linear-gradient(90deg, var(--accent), #2dd4bf);
  padding: 0.45rem 0.75rem;
  border-radius: 10px;
  font-weight: 600;
}

.button.ghost {
  background: transparent;
  color: var(--accent);
}

code, pre {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

pre {
  margin: 0;
  padding: 0.9rem;
  overflow: auto;
  border-radius: 10px;
  background: var(--code-bg);
  border: 1px solid var(--line);
  color: #dbeafe;
}

.tabs {
  display: inline-flex;
  gap: 0.4rem;
  margin-bottom: 0.7rem;
}

.tab {
  border: 1px solid var(--line);
  background: #111827;
  color: var(--muted);
  border-radius: 8px;
  padding: 0.3rem 0.6rem;
  cursor: pointer;
}

.tab.active {
  color: #022c38;
  background: var(--accent);
  border-color: var(--accent);
  font-weight: 600;
}

.accordion-item {
  border: 1px solid var(--line);
  border-radius: 12px;
  margin-bottom: 0.7rem;
  overflow: hidden;
  background: rgba(18, 26, 36, 0.8);
}

.accordion-head {
  width: 100%;
  background: transparent;
  color: var(--text);
  border: 0;
  padding: 0.75rem 0.9rem;
  text-align: left;
  font-size: 0.98rem;
  font-weight: 600;
  cursor: pointer;
}

.accordion-head:hover { background: rgba(34, 211, 238, 0.06); }
.accordion-body { display: none; padding: 0 0.9rem 0.9rem; }
.accordion-item.open .accordion-body { display: block; }

.doc-layout {
  display: grid;
  grid-template-columns: var(--sidebar-w) minmax(0, 1fr);
  min-height: calc(100vh - 56px);
}

.sidebar {
  border-right: 1px solid var(--line);
  background: rgba(13, 17, 23, 0.65);
  padding: 1rem 0.8rem;
  position: sticky;
  top: 56px;
  height: calc(100vh - 56px);
  overflow: auto;
}

.sidebar h3 { margin: 0 0 0.6rem; font-size: 0.92rem; color: var(--muted); }
.sidebar a {
  display: block;
  padding: 0.35rem 0.5rem;
  border-radius: 8px;
  margin-bottom: 0.2rem;
  color: #c5d4e6;
}
.sidebar a.active,
.sidebar a:hover { background: var(--bg-soft); text-decoration: none; }

.main-doc { padding: 1.4rem 1.2rem 2rem; }

.sidebar-toggle {
  margin-bottom: 1rem;
  border: 1px solid var(--line);
  background: #0f172a;
  color: var(--text);
  border-radius: 8px;
  padding: 0.35rem 0.65rem;
  cursor: pointer;
}

.doc-layout.collapsed { grid-template-columns: 70px minmax(0, 1fr); }
.doc-layout.collapsed .sidebar a span,
.doc-layout.collapsed .sidebar h3 { display: none; }
.doc-layout.collapsed .sidebar a { text-align: center; padding: 0.5rem 0.2rem; }

.footer {
  border-top: 1px solid var(--line);
  padding: 1.2rem 0;
  color: var(--muted);
  font-size: 0.92rem;
}

@media (max-width: 960px) {
  .grid-3, .grid-4, .grid-2 { grid-template-columns: 1fr; }
  .doc-layout { grid-template-columns: 1fr; }
  .sidebar {
    position: static;
    height: auto;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }
  .doc-layout.collapsed .sidebar { display: none; }
}
EOF

